-- Sallyport database setup. Runs once, at first database initialisation, after
-- Guacamole's own schema script (001-schema.sql, generated by ./sallyport init).

-- 1. Remove the default guacadmin / guacadmin account. There is deliberately no
--    Guacamole administrator: connections are managed with ./sallyport
--    load-targets, which writes to the database directly.
DELETE FROM guacamole_entity WHERE name = 'guacadmin' AND type = 'USER';

-- 2. Default group. Every connection is granted to this group by load-targets.
INSERT INTO guacamole_entity (name, type) VALUES ('sallyport-users', 'USER_GROUP');

INSERT INTO guacamole_user_group (entity_id, disabled)
SELECT entity_id, FALSE
FROM guacamole_entity
WHERE name = 'sallyport-users' AND type = 'USER_GROUP';

-- 3. Pomerium decides who may log in; Guacamole auto-creates an account for each
--    user it vouches for. This trigger puts every new account in the default group
--    so it can see the connections straight away.
CREATE FUNCTION sallyport_add_to_default_group() RETURNS trigger AS $$
BEGIN
  INSERT INTO guacamole_user_group_member (user_group_id, member_entity_id)
  SELECT g.user_group_id, NEW.entity_id
  FROM guacamole_user_group g
  JOIN guacamole_entity e ON e.entity_id = g.entity_id
  WHERE e.name = 'sallyport-users' AND e.type = 'USER_GROUP'
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER sallyport_new_user
AFTER INSERT ON guacamole_user
FOR EACH ROW EXECUTE FUNCTION sallyport_add_to_default_group();
